-- ═══════════════════════════════════════════════════════════════════════════
-- seed-category-taxonomy.sql — تکمیل تاکسونومی دسته‌ها (۳۵ اسلاگ کاتالوگ)
--
-- چرا: جدول products.category از ۳۵ اسلاگ استفاده می‌کند، ولی جدول categories
-- فقط ۵ رکورد داشت ⇒ ۳۰ دسته در پنل ادمین، ناوبری و متادیتا وجود نداشت.
--
-- ایمنی (این فایل فقط-افزودنی است):
--   • ON CONFLICT (slug) DO NOTHING ⇒ هیچ رکورد موجودی بازنویسی یا حذف نمی‌شود
--     (متن/تصویر کیوریت‌شدهٔ ادمین دست‌نخورده می‌ماند)
--   • هیچ محصولی تغییر نمی‌کند (products.categoryId اینجا ست نمی‌شود)
--   • اجرای دوباره بی‌اثر است (idempotent) — روی دیتابیس خالی هم کامل کار می‌کند
--   • نام/زیرشاخه/تصویر ۳۰ ردیف تازه همه از دادهٔ واقعی کاتالوگ گرفته شده‌اند
--
-- اجرا:  psql "$DATABASE_URL" -f scripts/seed-category-taxonomy.sql
--        یا:  DATABASE_URL=… npx tsx scripts/seed-category-taxonomy.ts
-- ═══════════════════════════════════════════════════════════════════════════

BEGIN;

-- هم‌گام‌سازی سکانس id: اسکریپت seed پروژه شناسه‌ها را صریح درج می‌کند و
-- سکانس عقب می‌ماند؛ بدون این خط، درج ردیف تازه با خطای categories_pkey می‌شکند.
SELECT setval(
  pg_get_serial_sequence('categories', 'id'),
  COALESCE((SELECT max(id) FROM categories), 1)
);

