ON CONFLICT (slug) DO NOTHING;

-- اتصال محصولات به رکورد دستهٔ خودشان (فقط جاهای خالی؛ هیچ محصولی جابه‌جا نمی‌شود)
UPDATE products p
   SET category_id = c.id
  FROM categories c
 WHERE c.slug = p.category
   AND p.category_id IS DISTINCT FROM c.id;

-- گزارش پس از اجرا: هر اسلاگِ محصول که رکورد دسته ندارد (باید صفر باشد)
DO $$
DECLARE missing int;
BEGIN
  SELECT count(*) INTO missing
  FROM (SELECT DISTINCT category FROM products) p
  LEFT JOIN categories c ON c.slug = p.category
  WHERE c.id IS NULL;
  RAISE NOTICE 'دسته‌های بدون رکورد: %', missing;
END $$;

COMMIT;
